const fecha = $('DevolverDatos').first().json.Fecha;
const horaSolicitada = $('DevolverDatos').first().json.Hora;
const prefijo = $('DevolverDatos').first().json.Prefijo;
const esCarmen = ['BN', 'OR'].includes(prefijo);

const horarios = esCarmen
  ? { lv: [['09:30','14:00'], ['16:00','19:30']], sab: [['10:00','14:00']], dom: null }
  : { lv: [['09:00','14:00'], ['16:00','19:00']], sab: null, dom: null };

const diaSemana = DateTime.fromFormat(fecha, 'yyyy-MM-dd', { zone: 'Europe/Madrid' }).weekday;

let bloques;
if (diaSemana === 7) bloques = horarios.dom;
else if (diaSemana === 6) bloques = horarios.sab;
else bloques = horarios.lv;

if (!bloques) {
  return [{ json: { alternativas: [], sinHuecos: true, textoAlternativas: '' } }];
}

// Generar candidatos en pasos de 30 min
let candidatos = [];
for (const [inicio, fin] of bloques) {
  let cursor = DateTime.fromFormat(`${fecha} ${inicio}`, 'yyyy-MM-dd HH:mm', { zone: 'Europe/Madrid' });
  const finBloque = DateTime.fromFormat(`${fecha} ${fin}`, 'yyyy-MM-dd HH:mm', { zone: 'Europe/Madrid' });
  while (cursor.plus({ hours: 1 }) <= finBloque) {
    candidatos.push(cursor);
    cursor = cursor.plus({ minutes: 30 });
  }
}

// Extraer eventos ocupados
const events = $input.all();
const busyRanges = events
  .filter(e => e.json.start?.dateTime || e.json.start?.date)
  .map(e => ({
    start: DateTime.fromISO(e.json.start.dateTime || e.json.start.date),
    end: DateTime.fromISO(e.json.end.dateTime || e.json.end.date)
  }));

// Filtrar slots que solapan con eventos
candidatos = candidatos.filter(c => {
  const endSlot = c.plus({ hours: 1 });
  return !busyRanges.some(b => c < b.end && endSlot > b.start);
});

// Ordenar cronológicamente (no por proximidad)
candidatos.sort((a, b) => a.toMillis() - b.toMillis());

const alternativas = candidatos.map(c => c.toFormat('HH:mm'));

// Agrupar por bloque para que Sara lo diga de forma natural
const manana = alternativas.filter(h => h < '14:00');
const tarde = alternativas.filter(h => h >= '16:00');

let textoAlternativas = '';
if (manana.length && tarde.length) {
  textoAlternativas = `Por la mañana tengo: ${manana.join(', ')}. Por la tarde: ${tarde.join(', ')}.`;
} else if (manana.length) {
  textoAlternativas = `Por la mañana tengo: ${manana.join(', ')}.`;
} else if (tarde.length) {
  textoAlternativas = `Por la tarde tengo: ${tarde.join(', ')}.`;
}

return [{ json: {
  alternativas,
  sinHuecos: alternativas.length === 0,
  textoAlternativas,
  debug_eventos: busyRanges.map(b => `${b.start.toFormat('HH:mm')}-${b.end.toFormat('HH:mm')}`)
} }];

assignments.value:
={{ $json.sinHuecos 
  ? "No disponible a esa hora y no quedan huecos libres ese día. ¿Podría proponer otro día?" 
  : "No disponible a las " + $('DevolverDatos').first().json.Hora + ". " + $json.textoAlternativas + " ¿Cuál le viene mejor?" }}

